                throw new ArgumentException("LQRP.solveInPlace: x.N must equal A.N_Cols");
            if (L.M_Rows != m || L.N_Cols != m)
                throw new ArgumentException("LQRP.solveInPlace: L must be m x m");
            if (P.N != m)
                throw new ArgumentException("LQRP.solveInPlace: P.N must equal A.M_Rows");
            if (v.N != n)
                throw new ArgumentException("LQRP.solveInPlace: v.N must equal A.N_Cols");

            // Negative relativeTolerance → library-standard rank threshold (same default as SVD.pinvSolve /
            // MatrixMetrics.rank). Also keeps tol >= 0, so a stray negative can't inflate rank.
            if (relativeTolerance < (float)0)
                relativeTolerance = (float)(math.max(m, n)) * Consts.floatZeroThreshold;

            if (n == 0)
                return new RankInfo { status = DirectSolveStatus.Success, rank = 0 };

            float zeroThreshold = Consts.floatZeroThreshold * Norms.LInf(in A);

            // Factor A in place (destroyed): reflectors in A's rows + L (separate), row pivot in P; no Q.
            var Qnull = default(floatMxN);
            lqrpKernel(ref A, ref L, ref Qnull, ref P, ref v, zeroThreshold, reconstructQ: false);

            // --- rank from L's non-increasing |diagonal| (tol = relativeTolerance·|L[0,0]|; NaN/zero L[0,0] → 0) ---
            float tol = relativeTolerance * math.abs(L[0, 0]);
            int rank = 0;
            for (int i = 0; i < m; i++)
            {
                if (math.abs(L[i, i]) > tol)
                    rank++;
                else
                    break;
            }

            if (rank == 0)
            {
                for (int j = 0; j < n; j++)
                    x[j] = (float)0;
                return new RankInfo { status = DirectSolveStatus.RankDeficient, rank = 0 };
            }

            int r = rank;

            // --- reduced RHS c = P·b, gathered into v[0..m-1] (v is free scratch after factorization;
            //     length n >= m). c[j] = b[P[j]]. ---
            for (int j = 0; j < m; j++)
                v[j] = b[P[j]];

            // --- basic forward-solve of L w = c on the leading r×r block (in place in v[0..m-1]);
            //     dependent rows dropped (w[r..m-1] = 0). Every used L[i,i] exceeds tol (divide-safe). ---
            for (int i = 0; i < r; i++)
            {
                float sum = (float)0;
                for (int j = 0; j < i; j++)
                    sum += L[i, j] * v[j];
                v[i] = (v[i] - sum) / L[i, i];
            }
            for (int i = r; i < m; i++)
                v[i] = (float)0;

            // --- x = Qᵀ w, applied straight from A's stored reflectors (no dense Q). Column ordering is
            //     untouched (only ROWS were permuted), so x needs no un-permute. ---
            LQ.applyQtFromReflectors(ref A, ref v, ref x);

            return new RankInfo
            {
                status = (r < m) ? DirectSolveStatus.RankDeficient : DirectSolveStatus.Success,
                rank = r
            };
        }

        /// <summary>
        /// solveInPlace with the default rank tolerance (max(m,n) · Consts.floatZeroThreshold,
        /// matching SVD.pinvSolve / MatrixMetrics.rank). See the primitive for full semantics.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo solveInPlace(ref floatMxN A, ref floatN b, ref floatN x,
                                            ref floatMxN L, ref Pivot P, ref floatN v)
        {
            return solveInPlace(ref A, ref b, ref x, ref L, ref P, ref v, (float)(-1));
        }

        /// <summary>
        /// Allocating convenience wrapper: allocates L (m×m), P (m-Pivot) and v (n) from Allocator.Temp
        /// and delegates to the zero-alloc primitive. DESTROYS A (see the primitive). Use the primitive
        /// in hot loops to avoid repeated Temp allocs.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo solveInPlace(ref floatMxN A, ref floatN b, ref floatN x, float relativeTolerance)
        {
            int m = A.M_Rows;
            int n = A.N_Cols;

            // Replicate the primitive's dimension checks BEFORE allocating, so a caller error can't leak
            // the Temp allocations (validate-before-alloc).
            if (m > n)
                throw new ArgumentException("LQRP.solveInPlace: A must be wide or square (M_Rows <= N_Cols)");
            if (b.N != m)
                throw new ArgumentException("LQRP.solveInPlace: b.N must equal A.M_Rows");
            if (x.N != n)
                throw new ArgumentException("LQRP.solveInPlace: x.N must equal A.N_Cols");

            var L = new floatMxN(m, m, Allocator.Temp, false);
            var P = new Pivot(m, Allocator.Temp);
            var v = new floatN(n, Allocator.Temp, false);
            var info = solveInPlace(ref A, ref b, ref x, ref L, ref P, ref v, relativeTolerance);
            v.Dispose();
            P.Dispose();
            L.Dispose();
            return info;
        }

        /// <summary>
        /// Allocating convenience wrapper with default tolerance (max(m,n) · Consts.floatZeroThreshold).
        /// DESTROYS A.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo solveInPlace(ref floatMxN A, ref floatN b, ref floatN x)
        {
            return solveInPlace(ref A, ref b, ref x, (float)(-1));
        }

        // ---- COD (complete orthogonal decomposition): MINIMUM-NORM rank-safe least squares ----
        //
        // solveInPlace above gives the BASIC solution (dependent rows dropped, w[r..] = 0). For a
        // rank-deficient wide A that is the minimum-norm solution ONLY when b is CONSISTENT; for an
        // inconsistent (genuine least-squares) b it is NOT — the below-diagonal block L21 couples the
        // independent variables into the dependent (dropped) equations, exactly the transpose-dual of
        // QRCP's R12 coupling. minNormSolveInPlace closes that gap and returns x = A⁺b (the pseudoinverse
        // / minimum-norm least-squares solution — the SAME answer SVD.pinvSolve gives) at
        // direct-factorization cost, mirroring QRCP.minNormSolveInPlace on the tall side.
        //
        // Derivation. P·A = L·Q with L = [L11 0; L21 L22] (L11 r×r lower-tri, full rank; the trailing
        // DIAGONAL below tol, so L22 ≈ 0 — but L21 is NOT small). Writing g = Q·x ∈ ℝ^m and c = P·b, the
        // residual is ‖L·g − c‖² = ‖L11·g1 − c1‖² + ‖L21·g1 + L22·g2 − c2‖². With L22 ≈ 0 the free block
        // g2 cannot reduce the residual, so it is fixed to 0 for minimum ‖x‖ (= ‖g‖, Q having orthonormal
        // rows); g1 minimizes ‖K·g1 − c‖ over BOTH row blocks at once, where K = [L11; L21] is the first
        // r columns of L (m×r, full COLUMN rank r). The basic solve instead takes g1 = L11⁻¹·c1 from the
        // top block only — which coincides with the least-squares g1 iff c is consistent (then L21·g1 = c2
        // automatically). So the whole solve is:
        //   1. factor P·A = L·Q in place (reflectors left in A; Q never formed), read rank r off L.
        //   2. c = P·b; g1 = argmin ‖K·g1 − c‖ via ordinary QR least-squares on K = L[:, 0..r).
        //   3. x = Qᵀ·[g1 ; 0] straight from A's stored reflectors (dependent block zeroed = min-norm).
        // Reuses QR.solveInPlace (the tall LS solve) and LQ.applyQtFromReflectors — no new kernel.

        // COD completion (r >= 1). On entry A holds the row-reflectors from lqrpKernel(reconstructQ:false),
        // L the lower-triangular factor, P the row pivot, r the detected rank. Fills x with the
        // minimum-norm least-squares solution. b is read-only (gathered into c = P·b). Allocates one set
        // of Allocator.Temp scratch (K/c/g1/w); the QR-LS on the m×r block is O(mr²), negligible against
        // the O(m²n) LQRP factorization that produced L.
        static unsafe void minNormCodFinish(ref floatMxN A, in floatN b, ref floatN x,
                                            ref floatMxN L, in Pivot P, int r)
        {
            int m = A.M_Rows;
            int n = A.N_Cols;

            // K = first r columns of L (m×r). K is full column rank r (L11's diagonal all exceed tol), so
            // the QR least-squares below is well-posed. c = P·b (reduced RHS, length m).
            var K = new floatMxN(m, r, Allocator.Temp, false);
            for (int i = 0; i < m; i++)
                for (int j = 0; j < r; j++)
                    K[i, j] = L[i, j];
            var c = new floatN(m, Allocator.Temp, false);
            for (int i = 0; i < m; i++)
                c[i] = b[P[i]];

            // g1 = argmin ‖K·g1 − c‖ (ordinary QR least-squares). QR.solveInPlace DESTROYS K and c —
            // both are private Temp copies.
            var g1 = new floatN(r, Allocator.Temp, false);
            QR.solveInPlace(ref K, ref c, ref g1);

            // w = [g1 ; 0] (length n; applyQtFromReflectors reads w[0..m) = [g1 ; 0_{m-r}] — the dependent
            // block zeroed for the minimum-norm choice). x = Qᵀ·w straight from A's reflectors (no dense
            // Q). Columns were never permuted (only rows), so x needs no un-permute.
            var w = new floatN(n, Allocator.Temp, false);
            for (int i = 0; i < r; i++) w[i] = g1[i];
            for (int i = r; i < n; i++) w[i] = (float)0;
            LQ.applyQtFromReflectors(ref A, ref w, ref x);

            w.Dispose();
            g1.Dispose();
            c.Dispose();
            K.Dispose();
        }

        /// <summary>
        /// LQRP-based MINIMUM-NORM rank-safe least-squares (complete orthogonal decomposition). Solves
        /// the underdetermined A x ≈ b (m ≤ n) for a possibly rank-deficient A and returns the
        /// pseudoinverse solution x = A⁺b — the minimum-2-norm vector among all least-squares minimizers,
        /// the SAME result SVD.pinvSolve gives, but at direct-factorization cost (one row-pivoted LQ plus
        /// one small QR on the m×r rank-revealed block). For a CONSISTENT b this coincides with the basic
        /// <see cref="solveInPlace(ref floatMxN, ref floatN, ref floatN, ref floatMxN, ref Pivot, ref floatN, float)"/>;
        /// the two differ only for an INCONSISTENT (genuine least-squares) rank-deficient system, where
        /// the basic solution is not minimum-norm (see the class remarks / the L21 coupling). At full row
        /// rank (r == m) both coincide with LQ.minNormSolve.
        ///
        /// DESTRUCTIVE FAST PATH (like solveInPlace): factors A's own buffer in place (reflectors, no Q).
        /// On return A is DESTROYED (stored reflectors + L's sub-diagonal); b is NOT modified. Numerical
        /// rank r is read from L's non-increasing diagonal (tol = relativeTolerance·|L[0,0]|; negative relativeTolerance
        /// auto-selects max(m,n)·Consts.floatZeroThreshold, matching SVD.pinvSolve / MatrixMetrics.rank).
        /// </summary>
        /// <param name="A">On entry A (m × n, m ≤ n); DESTROYED on exit (reflectors, NOT a factor — use decomp for L/Q).</param>
        /// <param name="b">Right-hand side, length m. Read-only (not modified). Must not alias x.</param>
        /// <param name="x">Output only; prior contents ignored; safe to allocate with uninit: true. Minimum-norm solution, length n.</param>
        /// <param name="L">Scratch: m × m (receives the lower-triangular factor; consumed).</param>
        /// <param name="P">Scratch: row Pivot of size m (reset internally).</param>
        /// <param name="v">Scratch: length EXACTLY n (Householder workspace).</param>
        /// <param name="relativeTolerance">Rank threshold ratio; tol = relativeTolerance·|L[0,0]|. Negative = auto default.</param>
        /// <returns>Status Success (r == m) or RankDeficient (r &lt; m, still a usable minimum-norm
        /// solution); rank = detected r. See <see cref="RankInfo.Solved"/>.</returns>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo minNormSolveInPlace(ref floatMxN A, ref floatN b, ref floatN x,
                                                   ref floatMxN L, ref Pivot P, ref floatN v, float relativeTolerance)
        {
            int m = A.M_Rows;
            int n = A.N_Cols;

            if (m > n)
                throw new ArgumentException("LQRP.minNormSolveInPlace: A must be wide or square (M_Rows <= N_Cols)");
            if (b.N != m)
                throw new ArgumentException("LQRP.minNormSolveInPlace: b.N must equal A.M_Rows");
            if (x.N != n)
                throw new ArgumentException("LQRP.minNormSolveInPlace: x.N must equal A.N_Cols");
            if (L.M_Rows != m || L.N_Cols != m)
                throw new ArgumentException("LQRP.minNormSolveInPlace: L must be m x m");
            if (P.N != m)
                throw new ArgumentException("LQRP.minNormSolveInPlace: P.N must equal A.M_Rows");
            if (v.N != n)
                throw new ArgumentException("LQRP.minNormSolveInPlace: v.N must equal A.N_Cols");

            if (relativeTolerance < (float)0)
                relativeTolerance = (float)(math.max(m, n)) * Consts.floatZeroThreshold;

            if (n == 0)
                return new RankInfo { status = DirectSolveStatus.Success, rank = 0 };

            float zeroThreshold = Consts.floatZeroThreshold * Norms.LInf(in A);

            // Factor A in place (destroyed): reflectors in A's rows + L (separate), row pivot in P; no Q.
            var Qnull = default(floatMxN);
            lqrpKernel(ref A, ref L, ref Qnull, ref P, ref v, zeroThreshold, reconstructQ: false);

            // Rank from L's non-increasing |diagonal| (tol = relativeTolerance·|L[0,0]|; NaN/zero L[0,0] → 0).
            float tol = relativeTolerance * math.abs(L[0, 0]);
            int r = 0;
            for (int i = 0; i < m; i++)
            {
                if (math.abs(L[i, i]) > tol) r++;
                else break;
            }

            if (r == 0)
            {
                for (int j = 0; j < n; j++) x[j] = (float)0;
                return new RankInfo { status = DirectSolveStatus.RankDeficient, rank = 0 };
            }

            unsafe { minNormCodFinish(ref A, in b, ref x, ref L, in P, r); }

            return new RankInfo
            {
                status = (r < m) ? DirectSolveStatus.RankDeficient : DirectSolveStatus.Success,
                rank = r
            };
        }

        /// <summary>minNormSolveInPlace with the default rank tolerance (max(m,n)·Consts.floatZeroThreshold,
        /// matching SVD.pinvSolve / MatrixMetrics.rank). See the primitive for full semantics.</summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo minNormSolveInPlace(ref floatMxN A, ref floatN b, ref floatN x,
                                                   ref floatMxN L, ref Pivot P, ref floatN v)
        {
            return minNormSolveInPlace(ref A, ref b, ref x, ref L, ref P, ref v, (float)(-1));
        }

        /// <summary>
        /// Allocating convenience wrapper: allocates L (m×m), P (m-Pivot) and v (n) from Allocator.Temp
        /// and delegates to the zero-alloc primitive. DESTROYS A (b is preserved). Use the primitive in
        /// hot loops to avoid repeated Temp allocs.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo minNormSolveInPlace(ref floatMxN A, ref floatN b, ref floatN x, float relativeTolerance)
        {
            int m = A.M_Rows;
            int n = A.N_Cols;

            // Replicate the primitive's dimension checks BEFORE allocating (validate-before-alloc).
            if (m > n)
                throw new ArgumentException("LQRP.minNormSolveInPlace: A must be wide or square (M_Rows <= N_Cols)");
            if (b.N != m)
                throw new ArgumentException("LQRP.minNormSolveInPlace: b.N must equal A.M_Rows");
            if (x.N != n)
                throw new ArgumentException("LQRP.minNormSolveInPlace: x.N must equal A.N_Cols");

            var L = new floatMxN(m, m, Allocator.Temp, false);
            var P = new Pivot(m, Allocator.Temp);
            var v = new floatN(n, Allocator.Temp, false);
            var info = minNormSolveInPlace(ref A, ref b, ref x, ref L, ref P, ref v, relativeTolerance);
            v.Dispose();
            P.Dispose();
            L.Dispose();
            return info;
        }

        /// <summary>Allocating convenience wrapper with default tolerance (max(m,n)·Consts.floatZeroThreshold).
        /// DESTROYS A (b preserved).</summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo minNormSolveInPlace(ref floatMxN A, ref floatN b, ref floatN x)
        {
            return minNormSolveInPlace(ref A, ref b, ref x, (float)(-1));
        }

        // ---- multi-RHS forms: a whole block of right-hand sides (each RHS a COLUMN of B / X) ----
        //
        // Three block solves, mirroring the vector forms + QRCP's block surface:
        //   solveInPlace(A,B,X)        — BASIC (truncated), FUSED: factor A in place, drop dependent
        //                                rows, X = Qᵀ[L11⁻¹·(P·B)_top ; 0]. A DESTROYED, B preserved.
        //   minNormSolveInPlace(A,B,X) — MINIMUM-NORM (x=A⁺B), FUSED: factor A in place, block QR-LS on
        //                                K=[L11;L21], X = Qᵀ[G1;0]. A DESTROYED, B preserved.
        //   minNormDecompSolve(L,Q,P,B,X) — MINIMUM-NORM from a precomputed LQRP factorization (reuse
        //                                one factorization across blocks); B preserved.

        // Shared reduced-RHS block for the min-norm (COD) solves: fills W (m×k) = [G1 ; 0], where
        // G1 = argmin ‖K·G1 − P·B‖ over the coupled m×r block K = [L11; L21] (= L's first r columns). The
        // caller then applies Qᵀ to W (via reflectors for the in-place solve, or a GEMM for the factor-
        // reuse solve). Allocates one set of Allocator.Temp scratch (K/C/G1); QR.solveInPlace DESTROYS
        // its private K and C copies.
        static unsafe void minNormReducedBlock(in floatMxN L, in Pivot P, in floatMxN B, int r, ref floatMxN W)
        {
            int m = L.M_Rows;      // L is m×m
            int k = B.N_Cols;

            var K = new floatMxN(m, r, Allocator.Temp, false);
            for (int i = 0; i < m; i++)
                for (int j = 0; j < r; j++)
                    K[i, j] = L[i, j];
            var C = new floatMxN(m, k, Allocator.Temp, false);
            for (int i = 0; i < m; i++)
            {
                int src = P[i];
                for (int c = 0; c < k; c++) C[i, c] = B[src, c];
            }

            var G1 = new floatMxN(r, k, Allocator.Temp, false);
            QR.solveInPlace(ref K, ref C, ref G1);

            float* Wp = W.Data.Ptr;
            float* Gp = G1.Data.Ptr;
            for (long e = 0; e < (long)r * k; e++) Wp[e] = Gp[e];        // W[0..r) = G1
            for (long e = (long)r * k; e < (long)m * k; e++) Wp[e] = (float)0;  // W[r..m) = 0

            G1.Dispose();
            C.Dispose();
            K.Dispose();
        }

        /// <summary>
        /// LQRP BASIC (truncated) solve of A X = B for a whole block of right-hand sides (m ≤ n) — the
        /// multi-RHS form of the vector <see cref="solveInPlace(ref floatMxN, ref floatN, ref floatN, ref floatMxN, ref Pivot, ref floatN, float)"/>.
        /// Each RHS is a COLUMN of B (m x k); X (n x k) receives the basic solution. For a rank-deficient
        /// A this is minimum-norm only when each column of B is consistent — otherwise use
        /// minNormSolveInPlace. DESTROYS A (reflectors); B is read-only.
        /// </summary>
        /// <param name="A">On entry A (m × n, m ≤ n); DESTROYED on exit (reflectors).</param>
        /// <param name="B">Right-hand sides (m x k). Read-only. Must not alias X.</param>
        /// <param name="X">Output only; prior contents ignored. Solution (n x k).</param>
        /// <param name="L">Scratch: m × m (receives the lower-triangular factor).</param>
        /// <param name="P">Scratch: row Pivot of size m (reset internally).</param>
        /// <param name="v">Scratch: length EXACTLY n.</param>
        public static unsafe RankInfo solveInPlace(ref floatMxN A, ref floatMxN B, ref floatMxN X,
                                                   ref floatMxN L, ref Pivot P, ref floatN v, float relativeTolerance)
        {
            int m = A.M_Rows;
            int n = A.N_Cols;
            int k = B.N_Cols;

            if (m > n)
                throw new ArgumentException("LQRP.solveInPlace: A must be wide or square (M_Rows <= N_Cols)");
            if (B.M_Rows != m)
                throw new ArgumentException("LQRP.solveInPlace: B.M_Rows must equal A.M_Rows");
            if (X.M_Rows != n)
                throw new ArgumentException("LQRP.solveInPlace: X.M_Rows must equal A.N_Cols");
            if (X.N_Cols != k)
                throw new ArgumentException("LQRP.solveInPlace: X.N_Cols must equal B.N_Cols");
            if (L.M_Rows != m || L.N_Cols != m)
                throw new ArgumentException("LQRP.solveInPlace: L must be m x m");
            if (P.N != m)
                throw new ArgumentException("LQRP.solveInPlace: P.N must equal A.M_Rows");
            if (v.N != n)
                throw new ArgumentException("LQRP.solveInPlace: v.N must equal A.N_Cols");

            if (relativeTolerance < (float)0)
                relativeTolerance = (float)(math.max(m, n)) * Consts.floatZeroThreshold;

            if (n == 0)
                return new RankInfo { status = DirectSolveStatus.Success, rank = 0 };

            float zeroThreshold = Consts.floatZeroThreshold * Norms.LInf(in A);
            var Qnull = default(floatMxN);
            lqrpKernel(ref A, ref L, ref Qnull, ref P, ref v, zeroThreshold, reconstructQ: false);

            float tol = relativeTolerance * math.abs(L[0, 0]);
            int r = 0;
            for (int i = 0; i < m; i++)
            {
                if (math.abs(L[i, i]) > tol) r++;
                else break;
            }

            // W (m×k): reduced RHS C = P·B, then basic forward-solve of L W = C on the leading r×r block
            // (dependent rows dropped: W[r..m) = 0). Then X = Qᵀ W.
            var W = new floatMxN(m, k, Allocator.Temp, false);
            float* Wp = W.Data.Ptr;
            for (int i = 0; i < m; i++)
            {
                int src = P[i];
                float* Wi = Wp + (long)i * k;
                for (int c = 0; c < k; c++) Wi[c] = B[src, c];       // C = P·B
            }
            for (int i = 0; i < r; i++)
            {
                float* Wi = Wp + (long)i * k;
                for (int j = 0; j < i; j++)
                    UnsafeOP.axpy(Wi, Wp + (long)j * k, -L[i, j], k);
                float inv = (float)1 / L[i, i];
                for (int c = 0; c < k; c++) Wi[c] *= inv;
            }
            for (long e = (long)r * k; e < (long)m * k; e++) Wp[e] = (float)0;

            LQ.applyQtFromReflectors(ref A, ref W, ref X);
            W.Dispose();

            return new RankInfo
            {
                status = (r < m) ? DirectSolveStatus.RankDeficient : DirectSolveStatus.Success,
                rank = r
            };
        }

        /// <summary>Multi-RHS basic solveInPlace with the default rank tolerance. See the primitive.</summary>
        public static RankInfo solveInPlace(ref floatMxN A, ref floatMxN B, ref floatMxN X,
                                            ref floatMxN L, ref Pivot P, ref floatN v)
        {
            return solveInPlace(ref A, ref B, ref X, ref L, ref P, ref v, (float)(-1));
        }

        /// <summary>Allocating multi-RHS basic convenience: allocates L (m×m), P (m) and v (n) from
        /// Allocator.Temp. DESTROYS A (B preserved). Use the scratch overload in hot loops.</summary>
        public static RankInfo solveInPlace(ref floatMxN A, ref floatMxN B, ref floatMxN X, float relativeTolerance)
        {
            int m = A.M_Rows;
            int n = A.N_Cols;

            if (m > n)
                throw new ArgumentException("LQRP.solveInPlace: A must be wide or square (M_Rows <= N_Cols)");
            if (B.M_Rows != m)
                throw new ArgumentException("LQRP.solveInPlace: B.M_Rows must equal A.M_Rows");
            if (X.M_Rows != n)
                throw new ArgumentException("LQRP.solveInPlace: X.M_Rows must equal A.N_Cols");
            if (X.N_Cols != B.N_Cols)
                throw new ArgumentException("LQRP.solveInPlace: X.N_Cols must equal B.N_Cols");

            var L = new floatMxN(m, m, Allocator.Temp, false);
            var P = new Pivot(m, Allocator.Temp);
            var v = new floatN(n, Allocator.Temp, false);
            var info = solveInPlace(ref A, ref B, ref X, ref L, ref P, ref v, relativeTolerance);
            v.Dispose();
            P.Dispose();
            L.Dispose();
            return info;
        }

        /// <summary>Allocating multi-RHS basic convenience with default tolerance. DESTROYS A (B preserved).</summary>
        public static RankInfo solveInPlace(ref floatMxN A, ref floatMxN B, ref floatMxN X)
        {
            return solveInPlace(ref A, ref B, ref X, (float)(-1));
        }

        /// <summary>
        /// LQRP MINIMUM-NORM (pseudoinverse) least-squares of A X = B for a whole block of right-hand
        /// sides (m ≤ n) — the multi-RHS form of the vector
        /// <see cref="minNormSolveInPlace(ref floatMxN, ref floatN, ref floatN, ref floatMxN, ref Pivot, ref floatN, float)"/>.
        /// Each RHS is a COLUMN of B (m x k); X (n x k) receives x = A⁺B. FUSED: factors A in place and
        /// never forms Q. DESTROYS A (reflectors); B is read-only.
        /// </summary>
        /// <param name="A">On entry A (m × n, m ≤ n); DESTROYED on exit (reflectors).</param>
        /// <param name="B">Right-hand sides (m x k). Read-only. Must not alias X.</param>
        /// <param name="X">Output only; prior contents ignored. Minimum-norm solution (n x k).</param>
        /// <param name="L">Scratch: m × m (receives the lower-triangular factor).</param>
        /// <param name="P">Scratch: row Pivot of size m (reset internally).</param>
        /// <param name="v">Scratch: length EXACTLY n.</param>
        public static unsafe RankInfo minNormSolveInPlace(ref floatMxN A, ref floatMxN B, ref floatMxN X,
                                                          ref floatMxN L, ref Pivot P, ref floatN v, float relativeTolerance)
        {
            int m = A.M_Rows;
            int n = A.N_Cols;
            int k = B.N_Cols;

            if (m > n)
                throw new ArgumentException("LQRP.minNormSolveInPlace: A must be wide or square (M_Rows <= N_Cols)");
            if (B.M_Rows != m)
                throw new ArgumentException("LQRP.minNormSolveInPlace: B.M_Rows must equal A.M_Rows");
            if (X.M_Rows != n)
                throw new ArgumentException("LQRP.minNormSolveInPlace: X.M_Rows must equal A.N_Cols");
            if (X.N_Cols != k)
                throw new ArgumentException("LQRP.minNormSolveInPlace: X.N_Cols must equal B.N_Cols");
            if (L.M_Rows != m || L.N_Cols != m)
                throw new ArgumentException("LQRP.minNormSolveInPlace: L must be m x m");
            if (P.N != m)
                throw new ArgumentException("LQRP.minNormSolveInPlace: P.N must equal A.M_Rows");
            if (v.N != n)
                throw new ArgumentException("LQRP.minNormSolveInPlace: v.N must equal A.N_Cols");

            if (relativeTolerance < (float)0)
                relativeTolerance = (float)(math.max(m, n)) * Consts.floatZeroThreshold;

            if (n == 0)
                return new RankInfo { status = DirectSolveStatus.Success, rank = 0 };

            float zeroThreshold = Consts.floatZeroThreshold * Norms.LInf(in A);
            var Qnull = default(floatMxN);
            lqrpKernel(ref A, ref L, ref Qnull, ref P, ref v, zeroThreshold, reconstructQ: false);

            float tol = relativeTolerance * math.abs(L[0, 0]);
            int r = 0;
            for (int i = 0; i < m; i++)
            {
                if (math.abs(L[i, i]) > tol) r++;
                else break;
            }

            if (r == 0)
            {
                float* Xz = X.Data.Ptr;
                for (long e = 0; e < (long)n * k; e++) Xz[e] = (float)0;
                return new RankInfo { status = DirectSolveStatus.RankDeficient, rank = 0 };
            }

            // W = [G1 ; 0] (block QR-LS on K = [L11; L21]); X = Qᵀ W straight from A's reflectors.
            var W = new floatMxN(m, k, Allocator.Temp, false);
            minNormReducedBlock(in L, in P, in B, r, ref W);
            LQ.applyQtFromReflectors(ref A, ref W, ref X);
            W.Dispose();

            return new RankInfo
            {
                status = (r < m) ? DirectSolveStatus.RankDeficient : DirectSolveStatus.Success,
                rank = r
            };
        }

        /// <summary>Multi-RHS min-norm solveInPlace with the default rank tolerance. See the primitive.</summary>
        public static RankInfo minNormSolveInPlace(ref floatMxN A, ref floatMxN B, ref floatMxN X,
                                                   ref floatMxN L, ref Pivot P, ref floatN v)
        {
            return minNormSolveInPlace(ref A, ref B, ref X, ref L, ref P, ref v, (float)(-1));
        }

        /// <summary>Allocating multi-RHS min-norm convenience: allocates L (m×m), P (m) and v (n) from
        /// Allocator.Temp. DESTROYS A (B preserved). Use the scratch overload in hot loops.</summary>
        public static RankInfo minNormSolveInPlace(ref floatMxN A, ref floatMxN B, ref floatMxN X, float relativeTolerance)
        {
            int m = A.M_Rows;
            int n = A.N_Cols;

            if (m > n)
                throw new ArgumentException("LQRP.minNormSolveInPlace: A must be wide or square (M_Rows <= N_Cols)");
            if (B.M_Rows != m)
                throw new ArgumentException("LQRP.minNormSolveInPlace: B.M_Rows must equal A.M_Rows");
            if (X.M_Rows != n)
                throw new ArgumentException("LQRP.minNormSolveInPlace: X.M_Rows must equal A.N_Cols");
            if (X.N_Cols != B.N_Cols)
                throw new ArgumentException("LQRP.minNormSolveInPlace: X.N_Cols must equal B.N_Cols");

            var L = new floatMxN(m, m, Allocator.Temp, false);
            var P = new Pivot(m, Allocator.Temp);
            var v = new floatN(n, Allocator.Temp, false);
            var info = minNormSolveInPlace(ref A, ref B, ref X, ref L, ref P, ref v, relativeTolerance);
            v.Dispose();
            P.Dispose();
            L.Dispose();
            return info;
        }

        /// <summary>Allocating multi-RHS min-norm convenience with default tolerance. DESTROYS A (B preserved).</summary>
        public static RankInfo minNormSolveInPlace(ref floatMxN A, ref floatMxN B, ref floatMxN X)
        {
            return minNormSolveInPlace(ref A, ref B, ref X, (float)(-1));
        }

        /// <summary>
        /// LQRP MINIMUM-NORM least-squares for a whole block of right-hand sides, from a precomputed
        /// LQRP factorization (P·A = L·Q, from <see cref="decomp(in floatMxN, ref floatMxN, ref floatMxN, ref Pivot)"/>)
        /// — reuse one factorization across blocks. Each RHS is a COLUMN of B (m x k, preserved); X (n x k)
        /// receives x = A⁺B. Uses the dense Q for the final Qᵀ apply (GEMM). Returns <see cref="RankInfo"/>.
        /// </summary>
        /// <param name="L">Lower-triangular factor (m x m) from decomp.</param>
        /// <param name="Q">Row-orthonormal factor (m x n) from decomp.</param>
        /// <param name="P">Row pivot from decomp.</param>
        /// <param name="B">Right-hand sides (m x k). Preserved. Must not alias X.</param>
        /// <param name="X">Output only; prior contents ignored. Minimum-norm solution (n x k).</param>
        public static unsafe RankInfo minNormDecompSolve(ref floatMxN L, ref floatMxN Q, in Pivot P,
                                                         ref floatMxN B, ref floatMxN X, float relativeTolerance)
        {
            int m = Q.M_Rows;
            int n = Q.N_Cols;
            int k = B.N_Cols;

            if (m > n)
                throw new ArgumentException("LQRP.minNormDecompSolve: Q must be wide or square (M_Rows <= N_Cols)");
            if (L.M_Rows != m || L.N_Cols != m)
                throw new ArgumentException("LQRP.minNormDecompSolve: L must be m x m");
            if (B.M_Rows != m)
                throw new ArgumentException("LQRP.minNormDecompSolve: B.M_Rows must equal Q.M_Rows");
            if (X.M_Rows != n)
                throw new ArgumentException("LQRP.minNormDecompSolve: X.M_Rows must equal Q.N_Cols");
            if (X.N_Cols != k)
                throw new ArgumentException("LQRP.minNormDecompSolve: X.N_Cols must equal B.N_Cols");
            if (P.N != m)
                throw new ArgumentException("LQRP.minNormDecompSolve: P.N must equal Q.M_Rows");

            if (relativeTolerance < (float)0)
                relativeTolerance = (float)(math.max(m, n)) * Consts.floatZeroThreshold;

            if (n == 0)
                return new RankInfo { status = DirectSolveStatus.Success, rank = 0 };

            float tol = relativeTolerance * math.abs(L[0, 0]);
            int r = 0;
            for (int i = 0; i < m; i++)
            {
                if (math.abs(L[i, i]) > tol) r++;
                else break;
            }

            if (r == 0)
            {
                float* Xz = X.Data.Ptr;
                for (long e = 0; e < (long)n * k; e++) Xz[e] = (float)0;
                return new RankInfo { status = DirectSolveStatus.RankDeficient, rank = 0 };
            }

            // W = [G1 ; 0]; X = Qᵀ W via a GEMM against the dense Q (Qᵀ is n×m, W is m×k → X is n×k).
            var W = new floatMxN(m, k, Allocator.Temp, false);
            minNormReducedBlock(in L, in P, in B, r, ref W);
            Blas.dot(in Q, in W, ref X, transposeA: true);
            W.Dispose();

            return new RankInfo
            {
                status = (r < m) ? DirectSolveStatus.RankDeficient : DirectSolveStatus.Success,
                rank = r
            };
        }

        /// <summary>minNormDecompSolve with the default rank tolerance. See the primitive.</summary>
        public static RankInfo minNormDecompSolve(ref floatMxN L, ref floatMxN Q, in Pivot P,
                                                  ref floatMxN B, ref floatMxN X)
        {
            return minNormDecompSolve(ref L, ref Q, in P, ref B, ref X, (float)(-1));
        }

        // ---- BASIC factor-reuse solve (from a precomputed P·A = L·Q) ----

        // Shared reduced-RHS block for the BASIC factor-reuse solve: fills W (m×k) = [L11⁻¹·(P·B)_top ; 0]
        // — forward-substitution on L's leading r×r block, dependent rows dropped (W[r..m) = 0). The
        // transpose-dual of QRCP.finishFromQtB's back-solve, and the same inner loop the fused multi-RHS
        // solveInPlace runs inline. The caller then applies Qᵀ to W (a GEMM against the dense Q).
        static unsafe void basicReducedBlock(in floatMxN L, in Pivot P, in floatMxN B, int r, ref floatMxN W)
        {
            int m = L.M_Rows;      // L is m×m
            int k = B.N_Cols;

            float* Wp = W.Data.Ptr;
            for (int i = 0; i < m; i++)
            {
                int src = P[i];
                float* Wi = Wp + (long)i * k;
                for (int c = 0; c < k; c++) Wi[c] = B[src, c];       // C = P·B
            }
            for (int i = 0; i < r; i++)
            {
                float* Wi = Wp + (long)i * k;
                for (int j = 0; j < i; j++)
                    UnsafeOP.axpy(Wi, Wp + (long)j * k, -L[i, j], k);
                float inv = (float)1 / L[i, i];
                for (int c = 0; c < k; c++) Wi[c] *= inv;
            }
            for (long e = (long)r * k; e < (long)m * k; e++) Wp[e] = (float)0;
        }

        /// <summary>
        /// LQRP BASIC (truncated) least-squares for a whole block of right-hand sides, from a precomputed
        /// LQRP factorization (P·A = L·Q, from <see cref="decomp(in floatMxN, ref floatMxN, ref floatMxN, ref Pivot)"/>)
        /// — reuse one factorization across blocks. Each RHS is a COLUMN of B (m x k, preserved); X (n x k)
        /// receives the basic solution (minimum-norm only when each column of B is consistent — otherwise
        /// use <see cref="minNormDecompSolve(ref floatMxN, ref floatMxN, in Pivot, ref floatMxN, ref floatMxN, float)"/>).
        /// Uses the dense Q for the final Qᵀ apply (GEMM). Returns <see cref="RankInfo"/>.
        /// </summary>
        /// <param name="L">Lower-triangular factor (m x m) from decomp.</param>
        /// <param name="Q">Row-orthonormal factor (m x n) from decomp.</param>
        /// <param name="P">Row pivot from decomp.</param>
        /// <param name="B">Right-hand sides (m x k). Preserved. Must not alias X.</param>
        /// <param name="X">Output only; prior contents ignored. Solution (n x k).</param>
        public static unsafe RankInfo decompSolve(ref floatMxN L, ref floatMxN Q, in Pivot P,
                                                  ref floatMxN B, ref floatMxN X, float relativeTolerance)
        {
            int m = Q.M_Rows;
            int n = Q.N_Cols;
            int k = B.N_Cols;

            if (m > n)
                throw new ArgumentException("LQRP.decompSolve: Q must be wide or square (M_Rows <= N_Cols)");
            if (L.M_Rows != m || L.N_Cols != m)
                throw new ArgumentException("LQRP.decompSolve: L must be m x m");
            if (B.M_Rows != m)
                throw new ArgumentException("LQRP.decompSolve: B.M_Rows must equal Q.M_Rows");
            if (X.M_Rows != n)
                throw new ArgumentException("LQRP.decompSolve: X.M_Rows must equal Q.N_Cols");
            if (X.N_Cols != k)
                throw new ArgumentException("LQRP.decompSolve: X.N_Cols must equal B.N_Cols");
            if (P.N != m)
                throw new ArgumentException("LQRP.decompSolve: P.N must equal Q.M_Rows");

            if (relativeTolerance < (float)0)
                relativeTolerance = (float)(math.max(m, n)) * Consts.floatZeroThreshold;

            if (n == 0)
                return new RankInfo { status = DirectSolveStatus.Success, rank = 0 };

            float tol = relativeTolerance * math.abs(L[0, 0]);
            int r = 0;
            for (int i = 0; i < m; i++)
            {
                if (math.abs(L[i, i]) > tol) r++;
                else break;
            }

            if (r == 0)
            {
                float* Xz = X.Data.Ptr;
                for (long e = 0; e < (long)n * k; e++) Xz[e] = (float)0;
                return new RankInfo { status = DirectSolveStatus.RankDeficient, rank = 0 };
            }

            // W = [L11⁻¹·(P·B)_top ; 0]; X = Qᵀ W via a GEMM against the dense Q (Qᵀ is n×m, W is m×k).
            var W = new floatMxN(m, k, Allocator.Temp, false);
            basicReducedBlock(in L, in P, in B, r, ref W);
            Blas.dot(in Q, in W, ref X, transposeA: true);
            W.Dispose();

            return new RankInfo
            {
                status = (r < m) ? DirectSolveStatus.RankDeficient : DirectSolveStatus.Success,
                rank = r
            };
        }

        /// <summary>Multi-RHS basic decompSolve with the default rank tolerance. See the primitive.</summary>
        public static RankInfo decompSolve(ref floatMxN L, ref floatMxN Q, in Pivot P,
                                           ref floatMxN B, ref floatMxN X)
        {
            return decompSolve(ref L, ref Q, in P, ref B, ref X, (float)(-1));
        }

        // ---- single-RHS factor-reuse (vector forms of the block decompSolve / minNormDecompSolve) ----

        /// <summary>
        /// LQRP BASIC (truncated) least-squares from a precomputed factorization (P·A = L·Q), single
        /// right-hand side — the vector form of the block
        /// <see cref="decompSolve(ref floatMxN, ref floatMxN, in Pivot, ref floatMxN, ref floatMxN, float)"/>.
        /// b (length m) is preserved; x (length n) receives the basic solution (minimum-norm only for a
        /// consistent b — else use minNormDecompSolve). Wraps b/x as single-column blocks and delegates.
        /// </summary>
        public static RankInfo decompSolve(ref floatMxN L, ref floatMxN Q, in Pivot P,
                                           ref floatN b, ref floatN x, float relativeTolerance)
        {
            int m = Q.M_Rows;
            int n = Q.N_Cols;

            if (b.N != m)
                throw new ArgumentException("LQRP.decompSolve: b.N must equal Q.M_Rows");
            if (x.N != n)
                throw new ArgumentException("LQRP.decompSolve: x.N must equal Q.N_Cols");

            var B = new floatMxN(m, 1, Allocator.Temp, true);
            var X = new floatMxN(n, 1, Allocator.Temp, true);
            for (int i = 0; i < m; i++) B[i, 0] = b[i];
            var info = decompSolve(ref L, ref Q, in P, ref B, ref X, relativeTolerance);
            for (int j = 0; j < n; j++) x[j] = X[j, 0];
            X.Dispose();
            B.Dispose();
            return info;
        }

        /// <summary>Single-RHS basic decompSolve (factor-reuse) with the default rank tolerance. See the primitive.</summary>
        public static RankInfo decompSolve(ref floatMxN L, ref floatMxN Q, in Pivot P,
                                           ref floatN b, ref floatN x)
        {
            return decompSolve(ref L, ref Q, in P, ref b, ref x, (float)(-1));
        }

        /// <summary>
        /// LQRP MINIMUM-NORM (pseudoinverse) least-squares from a precomputed factorization (P·A = L·Q),
        /// single right-hand side — the vector form of the block
        /// <see cref="minNormDecompSolve(ref floatMxN, ref floatMxN, in Pivot, ref floatMxN, ref floatMxN, float)"/>.
        /// Returns x = A⁺b (the SAME answer SVD.pinvSolve gives). b (length m) preserved; x (length n) the
        /// minimum-norm solution. Wraps b/x as single-column blocks and delegates to the block COD solve.
        /// </summary>
        public static RankInfo minNormDecompSolve(ref floatMxN L, ref floatMxN Q, in Pivot P,
                                                  ref floatN b, ref floatN x, float relativeTolerance)
        {
            int m = Q.M_Rows;
            int n = Q.N_Cols;

            if (b.N != m)
                throw new ArgumentException("LQRP.minNormDecompSolve: b.N must equal Q.M_Rows");
            if (x.N != n)
                throw new ArgumentException("LQRP.minNormDecompSolve: x.N must equal Q.N_Cols");

            var B = new floatMxN(m, 1, Allocator.Temp, true);
            var X = new floatMxN(n, 1, Allocator.Temp, true);
            for (int i = 0; i < m; i++) B[i, 0] = b[i];
            var info = minNormDecompSolve(ref L, ref Q, in P, ref B, ref X, relativeTolerance);
            for (int j = 0; j < n; j++) x[j] = X[j, 0];
            X.Dispose();
            B.Dispose();
            return info;
        }

        /// <summary>Single-RHS min-norm decompSolve (factor-reuse) with the default rank tolerance. See the primitive.</summary>
        public static RankInfo minNormDecompSolve(ref floatMxN L, ref floatMxN Q, in Pivot P,
                                                  ref floatN b, ref floatN x)
        {
            return minNormDecompSolve(ref L, ref Q, in P, ref b, ref x, (float)(-1));
        }
    }
}
